"            const numericTip = parseFloat(tipAmount) || 0;
            const grandTotal = calculatedTotal + numericTip;

            let advancePaid = 0;
            let netAmountToPayToday = grandTotal;
            if (editingPreOrder) {
              advancePaid = parseFloat(editingPreOrder.advance_paid) || 0;
              netAmountToPayToday = Math.max(0, grandTotal - advancePaid);
            }

            const numericPaid = parseFloat(customerPaidAmount) || 0;
            const returnAmount = numericPaid > netAmountToPayToday ? numericPaid - netAmountToPayToday : 0;"

